--
-- Name: getdata; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.getdata AS
 SELECT ( SELECT count(*) AS count
           FROM public.movies) AS totalmovies,
    ( SELECT count(*) AS count
           FROM public.genres) AS totalgenres,
    ( SELECT count(*) AS count
           FROM public.search_logs) AS totalsearches,
    ( SELECT count(*) AS count
           FROM public.movie_cast) AS totalcast;


ALTER VIEW public.getdata OWNER TO postgres;

